import json, random, sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import diff_test, reference
from crosscheck.crosscheck import CrossCheck

def package(request):
    out=[]
    for stream in request["streams"]:
        e=CrossCheck(stream["topology"])
        out.append({"events": e.replay(stream["events"], stream["settings"])})
    return {"streams": out}

configs = [dict(name="max-trials-wide-eps", trials=32, epsilon=250000),
           dict(name="trials32-zero-eps", trials=32, epsilon=0),
           dict(name="trials1", trials=1, epsilon=0),
           dict(name="trials7-mid", trials=7, epsilon=49999)]
fails = cases = 0
for cfg in configs:
    for case in range(35):
        rng = random.Random((len(cfg["name"]) * 100 + case) * 7919)
        stream = diff_test.make_stream(rng, nodes=rng.randint(3, 8),
                                       ext=rng.randint(2, 4), events=14)
        st = stream["settings"]
        st["trials"] = cfg["trials"]; st["epsilon"] = cfg["epsilon"]
        st["cache_slots"] = rng.choice([0, 1, 2, 8])
        st["cutoff"] = rng.choice([[0,1],[1,1],[2,1],[3,1],[5,1],[6,1],[1,2],[5,2]])
        st["tau"] = rng.choice([0, 1, 500000, 999999, 1000000])
        st["bias"] = rng.choice([0, 1, 500000, 999999, 1000000])
        st["gamma"] = rng.choice([[0,1],[1,2],[1,1],[5,2],[3,7]])
        if cfg["name"] == "trials1":
            for link in stream["topology"]["links"]:
                link["capacity"] = rng.choice([0, 1, 2])
            for node in stream["topology"]["nodes"]:
                node["external_capacity"] = rng.choice([0, 1, 2])
        for event in stream["events"]:
            if event["op"] != "patch":
                continue
            if cfg["name"] == "trials1":
                if type(event["demands"]) is list:
                    event["demands"] = [[d[0], d[1], min(d[2], 1)]
                                        for d in event["demands"]
                                        if type(d) is list and len(d) == 3]
                if type(event["counters"]) is dict:
                    for cell in event["counters"].values():
                        if type(cell) is dict and cell.get("perturbed") is not None:
                            cell["perturbed"] = min(cell["perturbed"], 1)
        stream["events"] = list(stream["events"]) + [
            {"op": "repair", "id": "cache%d" % r} for r in range(3)]
        request = {"streams": [stream]}
        try:
            exp = reference.answer(request)
        except Exception as exc:
            print("reference error", cfg["name"], exc); continue
        got = package(request); cases += 1
        if got != exp:
            fails += 1
            print("MISMATCH", cfg["name"], case)
            print(json.dumps(request)[:1500])
            for a, b in zip(got["streams"][0]["events"], exp["streams"][0]["events"]):
                if a != b:
                    print("got", json.dumps(a)[:400]); print("exp", json.dumps(b)[:400]); break
            if fails > 2: break
    if fails > 2: break
print("adversarial cases", cases, "failures", fails)
PYEOF
